 일부 동작은 PostgreSQL이 판정합니다. 해당 테스트는 `IGAME_TEST_DSN`이 있을 때만 실행되며, 지정한 데이터베이스에 마이그레이션을 적용하고 데이터를 씁니다 — 버려도 되는 데이터베이스를 주세요.

+`make test-db`는 API와 database 패키지를 함께 실행합니다. database 테스트는 실제 embedded migration의 체크섬 거부, DDL·이력의 원자적 롤백, 재실행 안전성을 검증하며, 테스트마다 UUID 기반 전용 스키마와 모든 연결에 같은 `search_path`를 지정한 pool을 사용합니다. 종료 시 pool을 닫고 자기 스키마만 삭제하며 `public`으로 폴백하지 않습니다. API 테스트는 기본 스키마를 사용하므로 전체 DB가 일회용이어야 합니다. 테스트 계정에는 스키마 생성·삭제 및 테이블·함수·트리거 생성 권한이 필요하며, DB 전역 `pgcrypto` 확장은 관리자가 아래처럼 애플리케이션 테이블이 없는 전용 확장 스키마에 미리 한 번 설치해야 합니다. 이 확장 스키마도 테스트 연결의 검색 경로에 포함됩니다(테스트에서 삭제하지 않음). DSN이 설정된 뒤의 연결·권한·SQL 오류는 skip이 아닌 실패입니다.
+
 ```bash
 docker run -d --rm --name igame-test-db -e POSTGRES_PASSWORD=igame -e POSTGRES_USER=igame -e POSTGRES_DB=igame -p 15432:5432 postgres:17-alpine
-make test-db DSN='postgres://igame:igame@127.0.0.1:15432/igame?sslmode=disable'
+# pg_isready가 성공한 뒤 확장을 준비합니다.
+docker exec igame-test-db pg_isready -U igame -d igame
+docker exec igame-test-db psql -U igame -d igame -v ON_ERROR_STOP=1 -c 'CREATE SCHEMA igame_test_extensions; CREATE EXTENSION pgcrypto WITH SCHEMA igame_test_extensions'
+make test-db DSN='postgres://igame:igame@127.0.0.1:15432/igame?sslmode=disable&search_path=public,igame_test_extensions'
 docker rm -f igame-test-db
 ```

diff --git a/internal/database/database_pg_test.go b/internal/database/database_pg_test.go
new file mode 100644
index 0000000..3c54994
--- /dev/null
+++ b/internal/database/database_pg_test.go
@@ -0,0 +1,274 @@
+package database
+
+import (
+	"context"
+	"crypto/sha256"
+	"errors"
+	"fmt"
+	"os"
+	"reflect"
+	"slices"
+	"strings"
+	"testing"
+	"time"
+
+	"github.com/google/uuid"
+	"github.com/hkjang/igame/migrations"
+	"github.com/jackc/pgx/v5"
+	"github.com/jackc/pgx/v5/pgconn"
+	"github.com/jackc/pgx/v5/pgxpool"
+)
+
+// Each test owns a schema, never the API fixture's default schema. pgcrypto
+// must already exist at database scope so schema cleanup cannot remove it.
+func migrationPool(t *testing.T) (context.Context, *pgxpool.Pool, string) {
+	t.Helper()
+	dsn := os.Getenv("IGAME_TEST_DSN")
+	if dsn == "" {
+		t.Skip("IGAME_TEST_DSN is not set")
+	}
+	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
+	t.Cleanup(cancel)
+	admin, err := pgxpool.New(ctx, dsn)
+	if err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(admin.Close)
+	var extensionSchema string
+	if err := admin.QueryRow(ctx, `SELECT n.nspname FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='pgcrypto'`).Scan(&extensionSchema); err != nil {
+		t.Fatal(err)
+	}
+	if extensionSchema == "public" {
+		t.Fatal("prepare pgcrypto in a dedicated extension schema, not public (see README)")
+	}
+	schema := "migrate_" + strings.ReplaceAll(uuid.NewString(), "-", "")
+	quoted := pgx.Identifier{schema}.Sanitize()
+	if _, err := admin.Exec(ctx, `CREATE SCHEMA `+quoted); err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(func() {
+		cleanupCtx, cleanupCancel := context.WithTimeout(context.Background(), 10*time.Second)
+		defer cleanupCancel()
+		if _, err := admin.Exec(cleanupCtx, `DROP SCHEMA `+quoted+` CASCADE`); err != nil {
+			t.Errorf("drop owned schema: %v", err)
+		}
+	})
+	config, err := pgxpool.ParseConfig(dsn)
+	if err != nil {
+		t.Fatal(err)
+	}
+	// Startup parameters apply to every connection, including replacements.
+	// Omitting public also prevents an absent local table resolving to API data.
+	searchPath := quoted + "," + pgx.Identifier{extensionSchema}.Sanitize()
+	config.ConnConfig.RuntimeParams["search_path"] = searchPath
+	config.MaxConns = 2
+	pool, err := pgxpool.NewWithConfig(ctx, config)
+	if err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(pool.Close) // LIFO: close before dropping the schema.
+	// Hold both connections to verify the actual session setting on each one.
+	for range 2 {
+		conn, err := pool.Acquire(ctx)
+		if err != nil {
+			t.Fatal(err)
+		}
+		defer conn.Release()
+		var current, path string
+		if err := conn.QueryRow(ctx, `SELECT current_schema(), current_setting('search_path')`).Scan(&current, &path); err != nil {
+			t.Fatal(err)
+		}
+		if current != schema || path != searchPath {
+			t.Fatalf("unexpected schema/search_path: %q / %q", current, path)
+		}
+	}
+	return ctx, pool, schema
+}
+
+type migrationRecord struct {
+	Checksum  string
+	AppliedAt time.Time
+}
+
+func migrationHistory(t *testing.T, ctx context.Context, pool *pgxpool.Pool) map[string]migrationRecord {
+	t.Helper()
+	rows, err := pool.Query(ctx, `SELECT name, checksum, applied_at FROM schema_migrations ORDER BY name`)
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer rows.Close()
+	records := make(map[string]migrationRecord)
+	for rows.Next() {
+		var name string
+		var record migrationRecord
+		if err := rows.Scan(&name, &record.Checksum, &record.AppliedAt); err != nil {
+			t.Fatal(err)
+		}
+		records[name] = record
+	}
+	if err := rows.Err(); err != nil {
+		t.Fatal(err)
+	}
+	return records
+}
+
+func embeddedMigrationNames(t *testing.T) []string {
+	t.Helper()
+	names, err := migrationNames(migrations.Files)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if len(names) == 0 {
+		t.Fatal("no embedded migrations")
+	}
+	return names
+}
+
+func assertMigrationHistory(t *testing.T, history map[string]migrationRecord, names []string) {
+	t.Helper()
+	if len(history) != len(names) {
+		t.Fatalf("history has %d rows, want %d: %v", len(history), len(names), history)
+	}
+	for _, name := range names {
+		body, err := migrations.Files.ReadFile(name)
+		if err != nil {
+			t.Fatal(err)
+		}
+		record, ok := history[name]
+		if !ok || record.Checksum != fmt.Sprintf("%x", sha256.Sum256(body)) || record.AppliedAt.IsZero() {
+			t.Fatalf("invalid history for %s: %+v", name, record)
+		}
+	}
+}
+
+// Compare the whole seed row, including its generated ID and timestamps.
+func migrationSeed(t *testing.T, ctx context.Context, pool *pgxpool.Pool) string {
+	t.Helper()
+	var seed string
+	if err := pool.QueryRow(ctx, `SELECT to_jsonb(g)::text FROM games g WHERE slug='snake'`).Scan(&seed); err != nil {
+		t.Fatal(err)
+	}
+	return seed
+}
+
+func TestMigrateAppliesEmbeddedFilesAndIsIdempotent(t *testing.T) {
+	ctx, pool, _ := migrationPool(t)
+	if err := Migrate(ctx, pool); err != nil {
+		t.Fatal(err)
+	}
+	before := migrationHistory(t, ctx, pool)
+	assertMigrationHistory(t, before, embeddedMigrationNames(t))
+	seed := migrationSeed(t, ctx, pool)
+	if err := Migrate(ctx, pool); err != nil {
+		t.Fatal(err)
+	}
+	if after := migrationHistory(t, ctx, pool); !reflect.DeepEqual(before, after) {
+		t.Fatalf("rerun changed history: before=%v after=%v", before, after)
+	}
+	if after := migrationSeed(t, ctx, pool); after != seed {
+		t.Fatalf("rerun changed seed: before=%s after=%s", seed, after)
+	}
+}
+
+func TestMigrateRejectsChangedChecksumAndRecovers(t *testing.T) {
+	ctx, pool, _ := migrationPool(t)
+	if err := Migrate(ctx, pool); err != nil {
+		t.Fatal(err)
+	}
+	names := embeddedMigrationNames(t)
+	before := migrationHistory(t, ctx, pool)
+	seed := migrationSeed(t, ctx, pool)
+	name := names[0]
+	const corrupted = "deliberately-corrupted-checksum"
+	if _, err := pool.Exec(ctx, `UPDATE schema_migrations SET checksum=$1 WHERE name=$2`, corrupted, name); err != nil {
+		t.Fatal(err)
+	}
+	tampered := migrationHistory(t, ctx, pool)
+	err := Migrate(ctx, pool)
+	if err == nil || !strings.Contains(err.Error(), name) || !strings.Contains(err.Error(), "checksum") {
+		t.Fatalf("want checksum error naming %s, got %v", name, err)
+	}
+	if after := migrationHistory(t, ctx, pool); !reflect.DeepEqual(tampered, after) {
+		t.Fatalf("checksum refusal changed history: %v", after)
+	}
+	if _, err := pool.Exec(ctx, `UPDATE schema_migrations SET checksum=$1 WHERE name=$2`, before[name].Checksum, name); err != nil {
+		t.Fatal(err)
+	}
+	if err := Migrate(ctx, pool); err != nil {
+		t.Fatal(err)
+	}
+	if after := migrationHistory(t, ctx, pool); !reflect.DeepEqual(before, after) {
+		t.Fatalf("recovery changed history: %v", after)
+	}
+	if after := migrationSeed(t, ctx, pool); after != seed {
+		t.Fatal("checksum refusal/recovery changed seed")
+	}
+}
+
+func TestMigrateRollsBackDDLAndHistoryThenRetries(t *testing.T) {
+	ctx, pool, schema := migrationPool(t)
+	const target = "010_silent_sso.sql"
+	names := embeddedMigrationNames(t)
+	index := slices.Index(names, target)
+	if index < 1 {
+		t.Fatalf("expected migrations preceding %s", target)
+	}
+	// Fail the real history INSERT after 010 has executed its ALTER TABLE.
+	// The trigger also verifies that the DDL was visible inside that transaction.
+	_, err := pool.Exec(ctx, `
+ CREATE TABLE schema_migrations (
+  name text PRIMARY KEY, checksum text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now());
+ CREATE FUNCTION reject_migration_history() RETURNS trigger LANGUAGE plpgsql AS $$
+ BEGIN
+  IF NEW.name = '010_silent_sso.sql' THEN
+   IF NOT EXISTS (SELECT 1 FROM information_schema.columns
+      WHERE table_schema = TG_TABLE_SCHEMA AND table_name = 'oidc_flows' AND column_name = 'silent') THEN
+    RAISE EXCEPTION '010 DDL was not executed';
+   END IF;
+   RAISE EXCEPTION 'injected migration history failure' USING ERRCODE = 'P0001';
+  END IF;
+  RETURN NEW;
+ END $$;
+ CREATE TRIGGER reject_migration_history BEFORE INSERT ON schema_migrations
+ FOR EACH ROW EXECUTE FUNCTION reject_migration_history();`)
+	if err != nil {
+		t.Fatal(err)
+	}
+	err = Migrate(ctx, pool)
+	var pgErr *pgconn.PgError
+	if err == nil || !strings.Contains(err.Error(), target) || !errors.As(err, &pgErr) || pgErr.Code != "P0001" || pgErr.Message != "injected migration history failure" {
+		t.Fatalf("want injected INSERT error for %s, got %v", target, err)
+	}
+	before := migrationHistory(t, ctx, pool)
+	assertMigrationHistory(t, before, names[:index])
+	seed := migrationSeed(t, ctx, pool)
+	assertSilentColumn := func(want bool) {
+		t.Helper()
+		var exists bool
+		if err := pool.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM information_schema.columns
+   WHERE table_schema=$1 AND table_name='oidc_flows' AND column_name='silent')`, schema).Scan(&exists); err != nil {
+			t.Fatal(err)
+		}
+		if exists != want {
+			t.Fatalf("silent column exists=%v, want %v", exists, want)
+		}
+	}
+	assertSilentColumn(false)
+	if _, err := pool.Exec(ctx, `DROP TRIGGER reject_migration_history ON schema_migrations; DROP FUNCTION reject_migration_history()`); err != nil {
+		t.Fatal(err)
+	}
+	if err := Migrate(ctx, pool); err != nil {
+		t.Fatal(err)
+	}
+	after := migrationHistory(t, ctx, pool)
+	assertMigrationHistory(t, after, names)
+	assertSilentColumn(true)
+	for name, record := range before {
+		if after[name] != record {
+			t.Fatalf("retry rewrote completed migration %s", name)
+		}
+	}
+	if after := migrationSeed(t, ctx, pool); after != seed {
+		t.Fatal("retry changed previously committed seed")
+	}
+}

package database

import (
	"context"
	"crypto/sha256"
	"fmt"
	"io/fs"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/hkjang/igame/migrations"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"golang.org/x/crypto/bcrypt"
)

func Open(ctx context.Context, dsn string) (*pgxpool.Pool, error) {
	config, err := pgxpool.ParseConfig(dsn)
	if err != nil {
		return nil, fmt.Errorf("parse postgres DSN: %w", err)
	}
	config.MaxConns = 20
	config.MinConns = 2
	config.MaxConnLifetime = 30 * time.Minute
	config.MaxConnIdleTime = 5 * time.Minute
	pool, err := pgxpool.NewWithConfig(ctx, config)
	if err != nil {
		return nil, fmt.Errorf("open postgres: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("ping postgres: %w", err)
	}
	return pool, nil
}

// migrationFileName is the convention every schema migration follows: a
// zero-padded number, an underscore, a lower-case name, then ".sql".
var migrationFileName = regexp.MustCompile(`^([0-9]+)_[a-z0-9_]+\.sql$`)

// migrationNames lists the schema migrations in the order they must be applied.
//
// The files are ordered by their number rather than by their name. Sorting the
// names agrees with the numbers only while every number is padded to the same
// width, so the moment a "10_x.sql" joined the existing "001_".."009_" it would
// sort second and try to alter tables that do not exist yet — against a live
// database, halfway through a deployment. Sorting on the parsed number instead
// keeps the order the numbers describe no matter how they are written.
//
// A name that does not follow the convention, or a number used twice, is
// refused rather than applied at a guessed position: the files are compiled in,
// so this is a mistake in the repository that every start-up should report the
// same way instead of one that depends on the file system.
func migrationNames(fsys fs.FS) ([]string, error) {
	entries, err := fs.ReadDir(fsys, ".")
	if err != nil {
		return nil, err
	}
	type migration struct {
		number int
		name   string
	}
	found := make([]migration, 0, len(entries))
	seen := make(map[int]string, len(entries))
	for _, entry := range entries {
		name := entry.Name()
		if entry.IsDir() || !strings.HasSuffix(name, ".sql") {
			continue
		}
		match := migrationFileName.FindStringSubmatch(name)
		if match == nil {
			return nil, fmt.Errorf("migration %s is not named <number>_<name>.sql", name)
		}
		number, err := strconv.Atoi(match[1])
		if err != nil {
			return nil, fmt.Errorf("migration %s has an unreadable number: %w", name, err)
		}
		if other, duplicate := seen[number]; duplicate {
			return nil, fmt.Errorf("migrations %s and %s share the number %d", other, name, number)
		}
		seen[number] = name
		found = append(found, migration{number: number, name: name})
	}
	sort.Slice(found, func(i, j int) bool { return found[i].number < found[j].number })
	names := make([]string, 0, len(found))
	for _, entry := range found {
		names = append(names, entry.name)
	}
	return names, nil
}

func Migrate(ctx context.Context, pool *pgxpool.Pool) error {
	if _, err := pool.Exec(ctx, `CREATE TABLE IF NOT EXISTS schema_migrations (
		name text PRIMARY KEY, checksum text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now())`); err != nil {
		return fmt.Errorf("create schema migrations table: %w", err)
	}
	names, err := migrationNames(migrations.Files)
	if err != nil {
		return err
	}
	for _, name := range names {
		body, err := migrations.Files.ReadFile(name)
		if err != nil {
			return err
		}
		checksum := fmt.Sprintf("%x", sha256.Sum256(body))
		var existing string
		err = pool.QueryRow(ctx, `SELECT checksum FROM schema_migrations WHERE name=$1`, name).Scan(&existing)
		if err == nil {
			if existing != checksum {
				return fmt.Errorf("migration %s checksum changed", name)
			}
			continue
		}
		if err != pgx.ErrNoRows {
			return fmt.Errorf("read migration %s state: %w", name, err)
		}
		tx, err := pool.Begin(ctx)
		if err != nil {
			return err
		}
		if _, err = tx.Exec(ctx, string(body)); err == nil {
			_, err = tx.Exec(ctx, `INSERT INTO schema_migrations(name,checksum) VALUES($1,$2)`, name, checksum)
		}
		if err != nil {
			_ = tx.Rollback(ctx)
			return fmt.Errorf("apply migration %s: %w", name, err)
		}
		if err := tx.Commit(ctx); err != nil {
			return fmt.Errorf("commit migration %s: %w", name, err)
		}
	}
	return nil
}

// EnsureBootstrapAdmin creates the first local administrator. It intentionally
// does not overwrite a password later changed through the administrator UI.
func EnsureBootstrapAdmin(ctx context.Context, pool *pgxpool.Pool, username, password string) error {
	hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		return err
	}
	_, err = pool.Exec(ctx, `INSERT INTO users(username,display_name,password_hash,role,status)
		VALUES($1,$1,$2,'admin','active') ON CONFLICT(username) DO UPDATE SET
		password_hash=CASE WHEN users.password_hash='' THEN excluded.password_hash ELSE users.password_hash END,
		role='admin',status='active',updated_at=now()`, username, string(hash))
	if err != nil {
		return fmt.Errorf("ensure bootstrap administrator: %w", err)
	}
	return nil
}
package database

import (
	"strconv"
	"strings"
	"testing"
	"testing/fstest"

	"github.com/hkjang/igame/migrations"
)

func sqlFiles(names ...string) fstest.MapFS {
	files := fstest.MapFS{}
	for _, name := range names {
		files[name] = &fstest.MapFile{Data: []byte("SELECT 1;")}
	}
	return files
}

// The migrations are applied in the order they are numbered, and the tenth one
// is where sorting the names stops agreeing with that: "10_" sorts before
// "002_". Applying a brand new migration second, against a database that is
// already live, is a broken deployment that only happens once the tenth file
// exists.
func TestATenthMigrationIsAppliedAfterTheNinthAndNotSecond(t *testing.T) {
	names, err := migrationNames(sqlFiles("001_initial.sql", "002_extended.sql", "009_receipt_clock.sql", "10_battle_audit.sql", "11_later.sql"))
	if err != nil {
		t.Fatalf("migrationNames: %v", err)
	}
	want := []string{"001_initial.sql", "002_extended.sql", "009_receipt_clock.sql", "10_battle_audit.sql", "11_later.sql"}
	if strings.Join(names, ",") != strings.Join(want, ",") {
		t.Fatalf("migrations run as %v, want %v", names, want)
	}
}

// Two branches that each add "010_" merge cleanly and leave the order of the
// two schema changes up to whatever the file system reports first. Refusing to
// start says so once instead of applying them differently on different hosts.
func TestTwoMigrationsSharingANumberAreRefused(t *testing.T) {
	_, err := migrationNames(sqlFiles("001_initial.sql", "010_ranking.sql", "010_replay.sql"))
	if err == nil {
		t.Fatal("two migrations numbered 010 were accepted; their order is left to the file system")
	}
	if !strings.Contains(err.Error(), "010_ranking.sql") || !strings.Contains(err.Error(), "010_replay.sql") {
		t.Fatalf("the error does not name both files: %v", err)
	}
}

// A file that carries no number has no place in the sequence, so guessing one
// would apply it at an arbitrary point. It is reported instead.
func TestAMigrationWithoutANumberIsRefused(t *testing.T) {
	for _, name := range []string{"initial.sql", "v2_extended.sql", "003 realmguard.sql"} {
		if _, err := migrationNames(sqlFiles("001_initial.sql", name)); err == nil {
			t.Fatalf("%q was accepted as a migration despite not being numbered", name)
		}
	}
}

// Only the .sql files are schema migrations; migrations.go lives beside them.
func TestNonSQLFilesAreNotTreatedAsMigrations(t *testing.T) {
	files := sqlFiles("001_initial.sql")
	files["migrations.go"] = &fstest.MapFile{Data: []byte("package migrations")}
	files["README.md"] = &fstest.MapFile{Data: []byte("# schema")}
	names, err := migrationNames(files)
	if err != nil {
		t.Fatalf("migrationNames: %v", err)
	}
	if len(names) != 1 || names[0] != "001_initial.sql" {
		t.Fatalf("migrations are %v, want only 001_initial.sql", names)
	}
}

// The shipped migrations have to satisfy the convention the loader enforces,
// and their numbers have to run 1, 2, 3 ... with no gap: a gap means a file
// that a deployed database has already applied went missing from the tree.
func TestTheShippedMigrationsAreNumberedFromOneWithoutGaps(t *testing.T) {
	names, err := migrationNames(migrations.Files)
	if err != nil {
		t.Fatalf("the shipped migrations do not follow the naming convention: %v", err)
	}
	if len(names) == 0 {
		t.Fatal("no migrations are embedded; a fresh database would come up with no schema")
	}
	for i, name := range names {
		number, err := strconv.Atoi(migrationFileName.FindStringSubmatch(name)[1])
		if err != nil {
			t.Fatalf("migration %s has an unreadable number: %v", name, err)
		}
		if number != i+1 {
			t.Fatalf("migration %s is numbered %d but sits at position %d; a migration is missing", name, number, i+1)
		}
	}
}
